def solve(s):
    """Convert a Roman numeral to an integer.
    Handles standard symbols I V X L C D M with subtractive notation.
    Returns 0 for empty input and ignores surrounding whitespace and case.
    """
    if not isinstance(s, str):
        return 0
    s = s.strip().upper()
    if not s:
        return 0
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
                 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        if i + 1 < n and roman_map.get(s[i], 0) < roman_map.get(s[i+1], 0):
            total += roman_map[s[i+1]] - roman_map[s[i]]
            i += 2
        else:
            total += roman_map.get(s[i], 0)
            i += 1
    return total

