def solve(nums):
    """Return the next lexicographic permutation of the list nums.
    If nums is the last permutation, return the sorted (lowest) permutation.
    Handles empty and single-element lists by returning a copy.
    """
    a = list(nums)  # make a copy
    n = len(a)
    if n <= 1:
        return a.copy()
    # Find the first index i from the end where a[i] < a[i+1]
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i == -1:
        return sorted(a)
    # Find rightmost element greater than a[i]
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    a[i], a[j] = a[j], a[i]
    # Reverse the suffix
    a[i + 1:] = reversed(a[i + 1:])
    return a

