def solve(grid):
    """Return the number of islands in the binary grid.
    An island is a group of adjacent 1s (horizontal or vertical).
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    visited = [[False]*m for _ in range(n)]
    def bfs(i,j):
        stack = [(i,j)]
        while stack:
            x,y = stack.pop()
            if 0 <= x < n and 0 <= y < m and not visited[x][y] and grid[x][y] == 1:
                visited[x][y] = True
                stack.extend([(x-1,y),(x+1,y),(x,y-1),(x,y+1)])
    islands = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                bfs(i,j)
    return islands

