        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    # Make a deep copy to avoid mutating original
    g = [row[:] for row in grid]
    count = 0
    def bfs(i,j):
        stack = [(i,j)]
        while stack:
            x,y = stack.pop()
            if 0 <= x < n and 0 <= y < m and g[x][y] == 1:
                g[x][y] = 0
                stack.extend([(x-1,y),(x+1,y),(x,y-1),(x,y+1)])
    for i in range(n):
        for j in range(m):
            if g[i][j] == 1:
                count += 1
                bfs(i,j)
    return count

