def solve(s):
    """Run-length encode the input.
    Accepts str, bytes, or bytearray. Returns a list of [character, count] pairs.
    Empty or non‑string input yields an empty list.
    """
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            # fallback: treat as empty
            return []
    if not isinstance(s, str) or not s:
        return []
    res = []
    prev = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == prev:
            cnt += 1
        else:
            res.append([prev, cnt])
            prev = ch
            cnt = 1
    res.append([prev, cnt])
    return res

