def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles any iterable of comparable items; non-comparable items are ignored.
    Returns 0 for None or non-iterable inputs.
    """
    # Guard for None or non-iterable
    if nums is None:
        return 0
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    import bisect
    tails = []  # tails[i] is the smallest possible tail of an increasing subseq of length i+1
    for x in iterator:
        # Skip items that cannot be compared to current tails
        try:
            i = bisect.bisect_left(tails, x)
        except TypeError:
            continue
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)
